chat:
---
config:
  flowchart:
    curve: linear
---
graph TD;
	__start__([<p>__start__</p>]):::first
	guard(guard)
	blocked_reply(blocked_reply)
	retrieve(retrieve)
	responder(responder)
	finalize(finalize)
	__end__([<p>__end__</p>]):::last
	__start__ --> guard;
	blocked_reply --> finalize;
	guard -. &nbsp;blocked&nbsp; .-> blocked_reply;
	guard -. &nbsp;respond&nbsp; .-> responder;
	guard -.-> retrieve;
	responder --> finalize;
	retrieve --> responder;
	finalize --> __end__;
	classDef default fill:#f2f0ff,line-height:1.2
	classDef first fill-opacity:0
	classDef last fill:#bfb6fc

